import { getSessionMeta, STATUS_LABELS, STATUS_COLORS } from '../utils/sessionMeta.js';

export default function TaskItem({
  task,
  onToggle,
  onEdit,
  onDelete,
  draggable = false,
  onDragStart,
  onDragOver,
  onDrop,
  onDragEnd,
  isDragging = false,
}) {
  const meta = getSessionMeta(task.type);

  return (
    <div
      draggable={draggable}
      onDragStart={onDragStart}
      onDragOver={onDragOver}
      onDrop={onDrop}
      onDragEnd={onDragEnd}
      className={`card flex items-center gap-3 p-4 transition ${task.completed ? 'opacity-60' : ''} ${
        isDragging ? 'ring-2 ring-primary-500' : ''
      } ${draggable ? 'cursor-grab active:cursor-grabbing' : ''}`}
    >
      {draggable && <span className="shrink-0 select-none text-gray-300 dark:text-gray-600">⠿</span>}

      <button
        onClick={() => onToggle(task)}
        aria-label="Toggle complete"
        className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2 transition ${
          task.completed
            ? 'border-primary-600 bg-primary-600 text-white'
            : 'border-gray-300 dark:border-gray-600'
        }`}
      >
        {task.completed && '✓'}
      </button>

      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-2">
          <span className="shrink-0" title={meta.label}>
            {meta.icon}
          </span>
          <span
            className={`truncate text-sm font-semibold text-gray-900 dark:text-white ${
              task.completed ? 'line-through' : ''
            }`}
          >
            {task.title}
          </span>
          <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${meta.badge}`}>{task.subject}</span>
          {task.subtopic && (
            <span className="rounded-full bg-gray-100 dark:bg-gray-800 px-2 py-0.5 text-xs font-medium text-gray-600 dark:text-gray-300">
              {task.subtopic}
            </span>
          )}
          {task.status && task.status !== 'not_started' && (
            <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${STATUS_COLORS[task.status]}`}>
              {STATUS_LABELS[task.status]}
            </span>
          )}
          {task.autoGenerated && (
            <span className="rounded-full bg-amber-50 dark:bg-amber-900/30 px-2 py-0.5 text-xs font-medium text-amber-700 dark:text-amber-300">
              Auto
            </span>
          )}
        </div>
        <p className="mt-0.5 text-xs text-gray-500 dark:text-gray-400">
          {task.startTime && task.endTime ? `${task.startTime}–${task.endTime} · ` : ''}
          {task.durationMinutes} min · Priority {task.priority} ·{' '}
          {new Date(task.date).toLocaleDateString()}
        </p>
        {task.notes && <p className="mt-1 text-xs text-gray-400 dark:text-gray-500">{task.notes}</p>}
      </div>

      <div className="flex shrink-0 items-center gap-2">
        <button onClick={() => onEdit(task)} className="btn-secondary !px-3 !py-1.5 text-xs">
          Edit
        </button>
        <button onClick={() => onDelete(task)} className="btn-danger">
          Delete
        </button>
      </div>
    </div>
  );
}
